import json,hashlib,statistics,collections
r=Path('dist/perf-patches/parse-architecture/disposal-receipt-runner/runtime');p=r/'fetch-warm/evidence/warm.json';d=json.loads(p.read_text());rows=[];groups=collections.defaultdict(list)
